def apply_search_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["QueryLog", "Synonym"]:
            schema_editor.create_model(apps.get_model("search", model_name))

def reverse_search_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["Synonym", "QueryLog"]:
            schema_editor.delete_model(apps.get_model("search", model_name))

